package com.yeyamo_mobile.api.feed_service.infrastructure.outbox;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.fasterxml.jackson.databind.ObjectMapper;
class FeedOutboxTests{@Test void writesVersionedEnvelope()throws Exception{FeedOutboxRepository repo=mock(FeedOutboxRepository.class);ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();new JpaFeedOutboxAdapter(repo,mapper).append("feed.post.projected","p1","c1",Map.of("postId","p1"));ArgumentCaptor<FeedOutboxEvent>c=ArgumentCaptor.forClass(FeedOutboxEvent.class);verify(repo).save(c.capture());var json=mapper.readTree(c.getValue().getPayload());assertEquals(1,json.get("eventVersion").asInt());assertEquals("feed-service",json.get("producer").asText());}}
